import csv
import json
from pathlib import Path
from types import SimpleNamespace

from bees_algorithm.configs import TSP_OPTIMA
from bees_algorithm.core.bee import Bee
from bees_algorithm.functions import sphere
from bees_algorithm.utils.plotting import generate_all_plots_bees
from bees_algorithm.utils.summarizer import summarize_all_bees
from bees_algorithm.utils.validators import (
    validate_continuous_vector,
    validate_tsp_tour,
)
from bees_algorithm.utils.writer import ExperimentWriter


def _fake_tracker(initial_fit: float, final_fit: float, solution, evals: int = 50):
    history = [
        initial_fit - (initial_fit - final_fit) * (i / max(evals - 1, 1))
        for i in range(evals)
    ]
    return SimpleNamespace(
        evaluations=evals,
        initial_best=Bee(solution, initial_fit),
        best_solution=Bee(solution, final_fit),
        history=history,
    )


def test_validate_tsp_tour_valid_and_invalid():
    coords = {1: [0.0, 0.0], 2: [3.0, 0.0], 3: [0.0, 4.0]}
    dist = [
        [0, 3, 4],
        [3, 0, 5],
        [4, 5, 0],
    ]
    ok, errs = validate_tsp_tour([1, 2, 3], coords, dist, 12)
    assert ok and errs == []

    bad, errs = validate_tsp_tour([2, 1, 3], coords, dist, 12)
    assert not bad and any("city 1" in e for e in errs)

    bad_len, errs = validate_tsp_tour([1, 2, 3], coords, dist, 99)
    assert not bad_len and any("recomputed" in e for e in errs)


def test_validate_continuous_vector():
    vec = [0.0, 0.0, 0.0]
    ok, errs = validate_continuous_vector(vec, 3, -5.12, 5.12, sphere, 0.0)
    assert ok and errs == []

    bad, errs = validate_continuous_vector(
        [6.0, 0.0, 0.0], 3, -5.12, 5.12, sphere, 36.0
    )
    assert not bad and any("out of bounds" in e for e in errs)


def test_writer_summarizer_and_plotting_end_to_end(tmp_path: Path):
    writer = ExperimentWriter(results_dir=tmp_path)
    writer.write_metadata(seeds=[45, 46])
    assert (tmp_path / "metadata.json").exists()

    # Populate Part A (berlin52 and ch150 across both neighbourhoods, 2 seeds each)
    writer.reset_part_a()
    berlin_route = list(range(1, 53))
    ch_route = list(range(1, 151))
    for instance, route in [("berlin52", berlin_route), ("ch150", ch_route)]:
        opt = TSP_OPTIMA[instance]
        for neigh, offset in [("SWAP", 500), ("REVERSE", 200)]:
            for idx, seed in enumerate([45, 46]):
                tracker = _fake_tracker(
                    opt + 3000, opt + offset + idx * 10, route, evals=20
                )
                writer.record_tsp_run(
                    instance=instance,
                    cities=len(route),
                    optimum=opt,
                    neighbourhood=neigh,
                    run_idx=idx + 1,
                    seed=seed,
                    tracker=tracker,
                    runtime_sec=0.12 + idx * 0.01,
                )
            hist_path = writer.flush_tsp_history(instance, neigh)
            assert hist_path is not None and hist_path.exists()

    # Populate Part B (all 4 functions at D=30 + rastrigin at D=10)
    writer.reset_part_b()
    for fn in ["sphere", "rosenbrock", "rastrigin", "ackley"]:
        dims = [10, 30] if fn == "rastrigin" else [30]
        for dim in dims:
            for idx, seed in enumerate([45, 46]):
                vec = [0.1 * (idx + 1)] * dim
                tracker = _fake_tracker(100.0, 1.5 + idx * 0.5, vec, evals=20)
                writer.record_continuous_run(
                    function_name=fn,
                    dimension=dim,
                    lower=-5.12,
                    upper=5.12,
                    global_minimum=0.0,
                    run_idx=idx + 1,
                    seed=seed,
                    tracker=tracker,
                    runtime_sec=0.05 + idx * 0.01,
                )
            hist_path = writer.flush_continuous_history(fn, dim)
            assert hist_path is not None and hist_path.exists()

    # Verify raw CSV & JSON
    with (tmp_path / "part_a_tsp" / "raw" / "runs.csv").open() as f:
        assert len(list(csv.DictReader(f))) == 8
    with (tmp_path / "part_b_continuous" / "raw" / "runs.csv").open() as f:
        assert len(list(csv.DictReader(f))) == 10
    sol_data = json.loads(
        (tmp_path / "part_a_tsp" / "raw" / "solutions.json").read_text()
    )
    assert "berlin52__REVERSE__seed_45" in sol_data

    # Summarize
    summaries = summarize_all_bees(results_dir=tmp_path)
    assert len(summaries["tsp"]) == 4
    assert len(summaries["continuous"]) == 5
    assert (tmp_path / "part_a_tsp" / "tables" / "summary_tsp.csv").exists()
    assert (tmp_path / "part_a_tsp" / "tables" / "summary_tsp.md").exists()
    assert (
        tmp_path / "part_b_continuous" / "tables" / "summary_continuous.csv"
    ).exists()
    assert (
        tmp_path / "part_b_continuous" / "tables" / "summary_continuous.md"
    ).exists()

    # Plot all 5 required figures
    plots = generate_all_plots_bees(results_dir=tmp_path)
    for name, path in plots.items():
        assert path is not None and path.exists() and path.stat().st_size > 0, name
